changeSet.sql:
create or alter procedure api.PostLookAssetPathPK
	@processGuid Uniqueidentifier
as
begin
		set nocount on;
		declare @totalcount bigint = 0,
				@runcount bigint = 1,
				@AssetTypeID int,
				@class int;

		create table #TempLookUpAssetPath (id int identity(1,1),AssetTypeID int);

		insert into #TempLookUpAssetPath (AssetTypeID)
		select distinct FT.AssetTypeID
		from api.InProcessLookUpField PF
		inner join FieldType FT on PF.FieldTypeID = FT.ID and FT.IsPartOfKey = 1 and Type = 'LOOKUP'

		select @totalcount = max(id)
		from #TempLookUpAssetPath ;
		while (@runcount <= @totalcount)
		begin
			select @AssetTypeID = AssetTypeID,
			@class = att.class
			from #TempLookUpAssetPath tp
			inner join assettype att on tp.AssetTypeID = att.id 
			where tp.id = @runcount;

			Insert into api.InProcessPostAssetPath(ProcessUid, AssetTypeID, AssetID)
			select distinct @processGuid, FT.AssetTypeID, PF.AssetID
			from FieldType FT
			inner join api.InProcessLookUpField PF on PF.FieldTypeID = FT.ID 
			where FT.AssetTypeID = @AssetTypeID;

			exec api.MergeAssetPaths null, @class, null, null, null,null, @processGuid,@AssetTypeID  ;

			set @runcount = @runcount + 1;
		end
end
